class Ubicacion {
  constructor(datos = {}) {
    this.status = datos.status || 'fail';
    this.country = datos.country || '';
    this.countryCode = datos.countryCode || '';
    this.region = datos.region || '';
    this.regionName = datos.regionName || '';
    this.city = datos.city || '';
    this.message = datos.message || '';
    this.lat = datos.lat ?? null;
    this.lon = datos.lon ?? null;
    this.query = datos.query || '';
  }

  esExitosa() {
    return this.status === 'success' && Boolean(this.countryCode);
  }

  descripcion() {
    if (!this.esExitosa()) return `Ubicación no disponible (${this.message || 'error de geolocalización'})`;
    return [this.city, this.regionName, this.country].filter(Boolean).join(', ');
  }

  resumen() {
    return {
      pais: this.country,
      codigoPais: this.countryCode,
      provincia: this.regionName,
      ciudad: this.city
    };
  }
}

class ZonaCobertura {
  static normalizar(texto) {
    if (!texto) return '';
    return String(texto)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/^(provincia de|canton de|distrito de)\s+/i, '')
      .trim();
  }

  static cubre(ubicacion, pedido) {
    // 1. Validar restricción explícita por provincia o cantón en datos de pedido
    const provForzada = this.normalizar(pedido.provincia);
    if (provForzada && !provForzada.includes('san jose')) {
      return false;
    }
    const cantonForzado = this.normalizar(pedido.canton);
    const cantonesFuera = ['heredia', 'alajuela', 'cartago', 'puntarenas', 'guanacaste', 'limon'];
    if (cantonForzado && cantonesFuera.some(c => cantonForzado.includes(c))) {
      return false;
    }

    // 2. Validar que la IP haya resuelto exitosamente en Costa Rica
    if (!ubicacion || !ubicacion.esExitosa()) return false;
    if (ubicacion.countryCode !== 'CR') return false;

    // 3. Validar que la región resuelta sea la provincia de San José
    const regionCod = (ubicacion.region || '').toUpperCase();
    const regionNom = this.normalizar(ubicacion.regionName);
    const ciudad = this.normalizar(ubicacion.city);

    return (regionCod === 'SJ' || regionNom.includes('san jose') || ciudad.includes('san jose'));
  }

  static esCantonCentral(ubicacion, pedido) {
    const ciudad = this.normalizar(ubicacion.city);
    const canton = this.normalizar(pedido.canton);
    return ciudad === 'san jose' || ciudad.includes('central') || canton === 'san jose' || canton.includes('central');
  }
}

class CalculadorEnvio {
  static TARIFA_CENTRAL = 2500;
  static TARIFA_RESTO = 3500;
  static UMBRAL_ENVIO_GRATIS = 50000;
  static LIMITE_PESO_BASE_KG = 5;
  static RECARGO_POR_KG = 300;

  static calcular(subtotal, pesoKg, ubicacion, pedido) {
    if (subtotal >= this.UMBRAL_ENVIO_GRATIS) {
      return { costo: 0, tarifaBase: 0, recargoPeso: 0, gratis: true };
    }
    const esCentral = ZonaCobertura.esCantonCentral(ubicacion, pedido);
    const tarifaBase = esCentral ? this.TARIFA_CENTRAL : this.TARIFA_RESTO;
    let recargoPeso = 0;
    if (pesoKg > this.LIMITE_PESO_BASE_KG) {
      recargoPeso = Math.ceil(pesoKg - this.LIMITE_PESO_BASE_KG) * this.RECARGO_POR_KG;
    }
    return {
      costo: tarifaBase + recargoPeso,
      tarifaBase,
      recargoPeso,
      gratis: false
    };
  }
}

class Pedido {
  constructor(datos = {}) {
    this.id = datos.id;
    this.cliente = datos.cliente || 'Anónimo';
    this.email = datos.email || datos.correo || '';
    this.ip = datos.ip || '';
    this.estado = datos.estado || 'pendiente';
    this.provincia = datos.provincia || '';
    this.canton = datos.canton || '';
    this.items = Array.isArray(datos.items) ? datos.items : [];
    this.pesoKg = Number(datos.pesoKg) || 1;
  }

  validarEstructura() {
    if (!this.items || this.items.length === 0) {
      return { valido: false, codigo: 'DATOS_INCOMPLETOS', motivo: 'Datos incompletos: el pedido no tiene productos.' };
    }
    if (!this.ip || typeof this.ip !== 'string') {
      return { valido: false, codigo: 'IP_INVALIDA', motivo: 'La IP del cliente falta o no tiene un formato válido.' };
    }
    return { valido: true };
  }

  calcularSubtotal() {
    return this.items.reduce((acc, it) => acc + (Number(it.precio) || 0) * (Number(it.cantidad) || 1), 0);
  }
}

// Mapeo seguro uno a uno por índice i evitando mezclas de pedidos
const geoItems = $input.all();
const pedidosItems = $('HTTP_Get_Pendientes').all();
const resultados = [];

for (let i = 0; i < geoItems.length; i++) {
  const pedidoData = pedidosItems[i].json;
  const geoData = geoItems[i].json;

  const pedido = new Pedido(pedidoData);
  const ubicacion = new Ubicacion(geoData);

  const validacion = pedido.validarEstructura();
  if (!validacion.valido) {
    const subtotal = pedido.calcularSubtotal();
    resultados.push({
      json: {
        ok: false,
        pedidoId: pedido.id,
        cliente: pedido.cliente,
        email: pedido.email,
        subtotal: subtotal,
        costoEnvio: 0,
        total: subtotal,
        motivo: validacion.motivo,
        codigoRechazo: validacion.codigo,
        patch: {
          estado: 'rechazado',
          motivoRechazo: validacion.motivo,
          codigoRechazo: validacion.codigo,
          subtotal: subtotal,
          costoEnvio: 0,
          total: subtotal,
          procesadoEn: new Date().toISOString()
        }
      }
    });
    continue;
  }

  const tieneCobertura = ZonaCobertura.cubre(ubicacion, pedido);
  const subtotal = pedido.calcularSubtotal();

  if (!tieneCobertura) {
    const ubicacionTexto = ubicacion.esExitosa() ? ubicacion.descripcion() : (pedido.provincia || 'Ubicación no verificable');
    const motivo = `Solo realizamos envíos a la provincia de San José, Costa Rica. Ubicación detectada o registrada: ${ubicacionTexto}.`;
    resultados.push({
      json: {
        ok: false,
        pedidoId: pedido.id,
        cliente: pedido.cliente,
        email: pedido.email,
        subtotal: subtotal,
        costoEnvio: 0,
        total: subtotal,
        motivo: motivo,
        codigoRechazo: 'FUERA_DE_COBERTURA',
        patch: {
          estado: 'rechazado',
          motivoRechazo: motivo,
          codigoRechazo: 'FUERA_DE_COBERTURA',
          subtotal: subtotal,
          costoEnvio: 0,
          total: subtotal,
          ubicacionDetectada: ubicacion.esExitosa() ? ubicacion.resumen() : null,
          procesadoEn: new Date().toISOString()
        }
      }
    });
  } else {
    const envio = CalculadorEnvio.calcular(subtotal, pedido.pesoKg, ubicacion, pedido);
    const total = subtotal + envio.costo;
    resultados.push({
      json: {
        ok: true,
        pedidoId: pedido.id,
        cliente: pedido.cliente,
        email: pedido.email,
        subtotal: subtotal,
        costoEnvio: envio.costo,
        total: total,
        motivo: null,
        patch: {
          estado: 'aprobado',
          motivoRechazo: null,
          codigoRechazo: null,
          subtotal: subtotal,
          costoEnvio: envio.costo,
          total: total,
          ubicacionDetectada: ubicacion.resumen(),
          procesadoEn: new Date().toISOString()
        }
      }
    });
  }
}

return resultados;

